class LayoutInfo {
  final String direction;
  final List<int> sizes;

  LayoutInfo(this.direction, this.sizes);

  int totalSize() {
    return sizes.fold(0, (sum, size) => sum + size);
  }

  double averageSize() {
    if (sizes.isEmpty) return 0;
    return totalSize() / sizes.length;
  }

  String describe() {
    return 'Direction: $direction, Items: ${sizes.length}, Total: ${totalSize()}';
  }
}

void main() {
  final row = LayoutInfo('horizontal', [100, 200, 150]);
  final column = LayoutInfo('vertical', [50, 80]);

  print(row.describe());
  print('Average: ${row.averageSize()}');
  print(column.describe());
}

class FlexBox {
  final int availableSpace;
  final List<int> flexValues;

  FlexBox(this.availableSpace, this.flexValues);

  int get _totalFlex => flexValues.fold(0, (sum, f) => sum + f);

  List<int> calculateSizes() {
    if (flexValues.isEmpty || _totalFlex == 0) return [];

    final sizes = flexValues
        .map((f) => (f * availableSpace / _totalFlex).floor())
        .toList();
    final allocated = sizes.fold(0, (sum, s) => sum + s);
    final remainder = availableSpace - allocated;

    if (sizes.isNotEmpty) {
      sizes[sizes.length - 1] += remainder;
    }
    return sizes;
  }
}

void main() {
  final box1 = FlexBox(300, [1, 2, 1]);
  final box2 = FlexBox(100, [1, 3]);

  print('300px với flex [1, 2, 1]: ${box1.calculateSizes()}');
  print('100px với flex [1, 3]: ${box2.calculateSizes()}');
}

class ResponsiveGrid {
  final double screenWidth;

  ResponsiveGrid(this.screenWidth);

  int getColumns() {
    if (screenWidth < 600) return 1;
    if (screenWidth <= 1024) return 2;
    return 3;
  }

  String getColumnsBreakpoint() {
    if (screenWidth < 600) return 'mobile';
    if (screenWidth <= 1024) return 'tablet';
    return 'desktop';
  }

  double calculateItemWidth(double padding) {
    final columns = getColumns();
    return (screenWidth - padding * (columns + 1)) / columns;
  }
}

void main() {
  final mobile = ResponsiveGrid(400);
  final tablet = ResponsiveGrid(800);
  final desktop = ResponsiveGrid(1400);

  for (final grid in [mobile, tablet, desktop]) {
    final columns = grid.getColumns();
    print('${grid.getColumnsBreakpoint()}: $columns cột, item = '
        '${grid.calculateItemWidth(16)}px');
  }
}

