class ResponsiveGrid {
  final double screenWidth;

  ResponsiveGrid(this.screenWidth);

  int getColumns() {
    if (screenWidth < 600) return 1;
    if (screenWidth <= 1024) return 2;
    return 3;
  }

  String getColumnsBreakpoint() {
    if (screenWidth < 600) return 'mobile';
    if (screenWidth <= 1024) return 'tablet';
    return 'desktop';
  }

  double calculateItemWidth(double padding) {
    final columns = getColumns();
    return (screenWidth - padding * (columns + 1)) / columns;
  }

  String describe() {
    final columns = getColumns();
    final width = calculateItemWidth(0);
    return 'Breakpoint: ${getColumnsBreakpoint()}, Columns: $columns, ItemWidth: $width';
  }
}

void main() {
